using System.Net;
using HikingGuide.Application.Logging;
using HikingGuide.Application.Maps;
using HikingGuide.Core.Models;
using HikingGuide.Infrastructure.Maps;
using HikingGuide.Infrastructure.Projects;

namespace HikingGuide.Infrastructure.Tests;
public sealed class MapRasterPersistenceTests
{
    private sealed class TemporaryDirectory:IDisposable {public string Path {get;}=System.IO.Path.Combine(@"F:\Codex\Temp","P101-raster-tests-"+Guid.NewGuid().ToString("N"));public TemporaryDirectory()=>Directory.CreateDirectory(Path);public void Dispose()=>Directory.Delete(Path,true);}
    private sealed class Log:ILoggingService {public void Debug(string s){}public void Information(string s){}public void Warning(string s){}public void Error(Exception e,string s){}public void Dispose(){}}
    private static GlobalSettingsService Service(string path)=>new(new(path),new Log(),new());
    [Fact]public async Task StackRoundTripsWithoutAnyProject(){using var d=new TemporaryDirectory();var s=Service(d.Path);await s.LoadAsync();var sources=s.Current.MapSources; s.Current.MapLayerStack=new(){BaseSourceId=sources[2].Id,Overlay1SourceId=sources[0].Id,Overlay1Visible=true,Overlay1Opacity=.45,Overlay2SourceId=sources[1].Id,Overlay2Visible=true,Overlay2Opacity=.7};await s.SaveAsync();var r=Service(d.Path);await r.LoadAsync();Assert.Equal(s.Current.MapLayerStack,r.Current.MapLayerStack);Assert.Contains("switch",r.Current.MapSources[2].UrlTemplate);}
    [Fact]public async Task MissingStackUpgradesToGermanyNotOldDefault(){using var d=new TemporaryDirectory();await File.WriteAllTextAsync(Path.Combine(d.Path,"settings.json"),"{\"defaultMapSourceId\":\"6c785f14-4c4f-45af-9e70-d8aa7af5f76c\",\"mapSources\":[]}");var s=Service(d.Path);await s.LoadAsync();Assert.Equal(GlobalMapLayerStackSettings.GermanyId,s.Current.MapLayerStack!.BaseSourceId);Assert.Null(s.Current.MapLayerStack.Overlay1SourceId);}
    [Fact]public async Task ActualCorruptSettingsFileRecoversOnLoad(){using var d=new TemporaryDirectory();var s=Service(d.Path);await s.LoadAsync();s.Current.MapLayerStack=new(){BaseSourceId=Guid.NewGuid(),BaseOpacity=2,Overlay1SourceId=s.Current.MapSources[0].Id,Overlay2SourceId=s.Current.MapSources[0].Id,Overlay2Visible=true};await File.WriteAllTextAsync(s.SettingsFilePath,System.Text.Json.JsonSerializer.Serialize(s.Current,new System.Text.Json.JsonSerializerOptions(System.Text.Json.JsonSerializerDefaults.Web)));var r=Service(d.Path);await r.LoadAsync();Assert.Equal(GlobalMapLayerStackSettings.GermanyId,r.Current.MapLayerStack!.BaseSourceId);Assert.Null(r.Current.MapLayerStack.Overlay1SourceId);Assert.Null(r.Current.MapLayerStack.Overlay2SourceId);Assert.Equal(1,r.Current.MapLayerStack.BaseOpacity);Assert.NotNull(r.MapSettingsWarning);}
    [Fact]public async Task HumanitarianDeletionNotUndoneByNextSave(){using var d=new TemporaryDirectory();var s=Service(d.Path);await s.LoadAsync();s.Current.MapSources.RemoveAll(v=>v.Id==GlobalSettingsService.HumanitarianSourceId);await s.SaveAsync();var r=Service(d.Path);await r.LoadAsync();Assert.DoesNotContain(r.Current.MapSources,v=>v.Id==GlobalSettingsService.HumanitarianSourceId);}
    [Fact]public async Task CorruptStackNormalizesWithWarning(){using var d=new TemporaryDirectory();var s=Service(d.Path);await s.LoadAsync();s.Current.MapLayerStack=new(){BaseSourceId=Guid.NewGuid(),BaseOpacity=10,Overlay1SourceId=Guid.NewGuid(),Overlay1Visible=true};await s.SaveAsync();Assert.Equal(GlobalMapLayerStackSettings.GermanyId,s.Current.MapLayerStack.BaseSourceId);Assert.Equal(1,s.Current.MapLayerStack.BaseOpacity);Assert.Null(s.Current.MapLayerStack.Overlay1SourceId);Assert.NotNull(s.MapSettingsWarning);}
    [Fact]public async Task DisabledOverlayClearsAndDisabledBaseFallsBack(){using var d=new TemporaryDirectory();var s=Service(d.Path);await s.LoadAsync();var a=s.Current.MapSources[2];var b=s.Current.MapSources[1];s.Current.MapLayerStack=new(){BaseSourceId=a.Id,Overlay1SourceId=b.Id,Overlay1Visible=true};a.Enabled=false;b.Enabled=false;await s.SaveAsync();Assert.Equal(GlobalMapLayerStackSettings.GermanyId,s.Current.MapLayerStack!.BaseSourceId);Assert.Null(s.Current.MapLayerStack.Overlay1SourceId);}
    [Fact]public async Task MissingGermanyWithInvalidBaseFallsBackToFirstExistingValidBase(){using var d=new TemporaryDirectory();var s=Service(d.Path);await s.LoadAsync();s.Current.MapSources.RemoveAll(v=>v.Id==GlobalMapLayerStackSettings.GermanyId);var first=s.Current.MapSources[0].Id;s.Current.MapLayerStack=new(){BaseSourceId=Guid.NewGuid()};await s.SaveAsync();Assert.Equal(first,s.Current.MapLayerStack.BaseSourceId);Assert.NotNull(s.MapSettingsWarning);}
    [Fact]public async Task MalformedJsonRecoversWithoutDeletingOriginalAndWarns(){using var d=new TemporaryDirectory();var s=Service(d.Path);await File.WriteAllTextAsync(s.SettingsFilePath,"{broken JSON");await s.LoadAsync();Assert.Equal(GlobalMapLayerStackSettings.GermanyId,s.Current.MapLayerStack!.BaseSourceId);Assert.NotNull(s.MapSettingsWarning);Assert.Equal("{broken JSON",await File.ReadAllTextAsync(s.SettingsFilePath));}
    [Fact]public async Task NullSourceEntryInDamagedSettingsIsSafelyRemoved(){using var d=new TemporaryDirectory();var s=Service(d.Path);await File.WriteAllTextAsync(s.SettingsFilePath,"{\"mapSources\":[null],\"mapLayerStack\":{}}");await s.LoadAsync();Assert.All(s.Current.MapSources,v=>Assert.NotNull(v));Assert.Equal(GlobalMapLayerStackSettings.GermanyId,s.Current.MapLayerStack!.BaseSourceId);}
    private sealed class Handler:HttpMessageHandler {public List<string> Hosts=[];protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c){Hosts.Add(r.RequestUri!.Host);return Task.FromResult(new HttpResponseMessage(r.RequestUri.Host.StartsWith("b.")?HttpStatusCode.ServiceUnavailable:HttpStatusCode.OK));}}
    [Fact]public async Task EverySwitchServerTestedEvenAfterFailure(){using var handler=new Handler();using var client=new HttpClient(handler);var s=new MapSourceDefinition{UrlTemplate="https://{switch:a,b,c}.example.com/{zoom}/{x}/{y}.png"};var r=await new MapSourceTestService(client,new(),new Log()).TestAsync(s);Assert.False(r.IsSuccess);Assert.Equal(new[]{"a.example.com","b.example.com","c.example.com"},handler.Hosts);Assert.Equal(3,r.Servers.Count);Assert.Equal(503,r.Servers[1].HttpStatusCode);Assert.True(r.Servers[2].IsSuccess);Assert.Contains("部分",r.Message);}
    [Fact]public async Task EverySwitchServerGetsOwnTokenLabels(){using var handler=new Handler();using var client=new HttpClient(handler);var r=await new MapSourceTestService(client,new(),new Log()).TestAsync(new(){UrlTemplate="https://{switch:a, b, c}.example.com/{z}/{x}/{y}.png"});Assert.Equal(new[]{"a","b","c"},r.Servers.Select(s=>s.ServerToken));}
}
